function validate([candies, extraCandies]) {
  if (!Array.isArray(candies) || candies.length < 2 || candies.length > 100) return 'candies needs 2 to 100 values.';
  if (candies.some(v => !Number.isInteger(v) || v < 1 || v > 100)) return 'Each kid has between 1 and 100 candies.';
  if (!Number.isInteger(extraCandies) || extraCandies < 1 || extraCandies > 50) return 'extraCandies is between 1 and 50.';
  return null;
}

