function kidsWithCandies(candies, extraCandies) {
  let most = 0;
  for (const count of candies) {
    most = Math.max(most, count);
  }
  const result = [];
  for (const count of candies) {
    result.push(count + extraCandies >= most);
  }
  return result;
}

