function kidsWithCandies(candies, extraCandies) {
  // Hand the extra candies to each kid in turn and compare with every other kid.
  return candies.map((mine, i) => {
    const total = mine + extraCandies;
    return candies.every((other, j) => j === i || other <= total);
  });
}

