function generate(rand, size) {
  const n = size === 'large' ? 100 : 2 + Math.floor(rand() * 7);
  const top = size === 'large' ? 100 : [3, 10, 100][Math.floor(rand() * 3)];
  const candies = Array.from({ length: n }, () => 1 + Math.floor(rand() * top));
  const extraCandies = 1 + Math.floor(rand() * Math.min(50, top + 2));
  return [candies, extraCandies];
}
